          "Below is the standalone Python 3.9+ verification engine computing the transfer operator eigen- system, Bessel character expansions, and scaling invariants directly from first principles. 1 from __future__ import annotations 2 import math 3 from typing import Tuple, Dict, Any, List 4 import numpy as np 5 import scipy.linalg 6 import scipy.special 7 8 class WilsonTransferMatrixEngine: 9 \"\"\" 10 Constructs and diagonalizes the gauge-invariant transfer matrix T 11 directly from the microscopic Wilson lattice action for SU(2). 12 Extracts the non-perturbative spectral gap Delta_hat without 13 assuming the Callan -Symanzik scaling formula. 14 \"\"\" 15 def __init__(self, j_max: float = 8.0, n_spatial_links: int = 4) -> None: 16 self.j_levels = [x * 0.5 for x in range(int(2 * j_max) + 1)] 17 self.dim = len(self.j_levels) 18 self.n_links = n_spatial_links 19 20 def compute_kinetic_operator(self, beta: float) -> np.ndarray: 21 \"\"\" 22 Computes diagonal kinetic matrix elements K_jj = (c_j(beta) / c_0(beta))^n_links 23 using exact SU(2) Peter-Weyl character coefficients: 24 c_j(beta) = (2/beta) * I_{2j+1}(beta). 25 \"\"\" 26 k_diag = np.zeros(self.dim, dtype=np.float64) 27 c0 = (2.0 / beta) * scipy.special.iv(1, beta) 28 for idx, j in enumerate(self.j_levels): 29 cj = (2.0 / beta) * scipy.special.iv(int(2 * j + 1), beta) 30 ratio = cj / c0 4",
